export type ValidationReceiptDto = {
    /**
     * Receiptid
     */
    receiptId: string;
    /**
     * Submissionid
     */
    submissionId: string;
    /**
     * Submissiondigest
     *
     * the exact submission content these gates examined
     */
    submissionDigest: string;
    /**
     * the canonical version the submission was checked against
     */
    checkedState: ProjectVersionDto;
    /**
     * Passed
     */
    passed: boolean;
    /**
     * Findings
     *
     * every finding the gates returned; empty is a real answer
     */
    findings: Array<ValidationFindingDto>;
};

